    @Override
    public Page<ChatQuestion> searchQuestionsByKeyword(String keyword, Pageable pageable) {
        log.debug("키워드로 질문 검색 쿼리 실행: keyword={}, page={}, size={}",
                keyword, pageable.getPageNumber(), pageable.getPageSize());

        BooleanBuilder builder = new BooleanBuilder();

        // 키워드가 있는 경우에만 검색 조건 추가
        if (StringUtils.hasText(keyword)) {
            builder.and(
                    chatQuestion.question.containsIgnoreCase(keyword)
                            .or(chatQuestion.answer.containsIgnoreCase(keyword))
            );
        }

        // 전체 개수 쿼리
        long total = queryFactory
                .selectFrom(chatQuestion)
                .where(builder)
                .fetchCount();

        // 데이터 쿼리
        List<ChatQuestion> results = queryFactory
                .selectFrom(chatQuestion)
                .where(builder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .orderBy(chatQuestion.createdAt.desc())
                .fetch();

        return new PageImpl<>(results, pageable, total);
    }
}    @Override
    public Page<FAQ> searchFAQs(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();

        if (keyword != null && !keyword.isEmpty()) {
            // 대소문자 무시와 한글 검색을 위한 like 사용
            builder.or(fAQ.question.like("%" + keyword + "%"))
                    .or(fAQ.answer.like("%" + keyword + "%"));
        }

        List<FAQ> results = queryFactory.selectFrom(fAQ)
                .where(builder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        long total = queryFactory.select(fAQ.count())
                .from(fAQ)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, total);
    }
